\begin{assumption}\label{ass:kinetic}
The function \(f_0\ge0\) is a smooth probability density and, for some
\(\beta>0\),
\begin{equation}\label{eq:initial-bol-bounds}
 \|f_0\|_{\Bol,2\beta}
 +\|\nabla_xf_0\|_{\Bol,2\beta}<\infty.
\end{equation}
There is a nonnegative classical solution \(f\) of \eqref{eq:boltzmann} with initial
datum \(f_0\) on a prescribed finite interval \([0,T]\), \(T>0\), such that
\begin{equation}\label{eq:kinetic-gaussian}
 M:=\sup_{0\le t\le T}\sup_{x,v}
       e^{2\beta|v|^2}f(t,x,v)<\infty.
\end{equation}
\end{assumption}

\begin{theorem}[Finite-dimensional fluctuation limit]\label{thm:main}
Under \Cref{ass:kinetic}, the centered Gaussian generalized field
\(\zeta\) with weak equation
\begin{equation}\label{eq:fluctuating-equation}
 \dd\zeta_t(\phi)=\zeta_t(A_t\phi)\,\dd t+\dd W_t(\phi)
\end{equation}
is well defined by its backward mild form on a scale of tests with small
Gaussian growth. Its initial field is independent of \(W\), and
\begin{align}
 \E[\zeta_0(\phi)\zeta_0(\psi)]
   &=\int_{\R^6}f_0\phi\psi\,\dd z,\label{eq:initial-covariance}\\
 \E[W_t(\phi)W_s(\psi)]
   &=\int_0^{t\wedge s}C_r(\phi,\psi)\,\dd r.\label{eq:noise-covariance}
\end{align}
The Gaussian noise \(W\) has independent increments. For every integer
\(m\ge1\), fixed times \(t_1,\ldots,t_m\in[0,T]\), and real tests
\(\phi_1,\ldots,\phi_m\in C_c^\infty(\R^6)\),
\begin{equation}\label{eq:main-convergence}
 \bigl(\zeta_{t_1}^\eps(\phi_1),\ldots,
       \zeta_{t_m}^\eps(\phi_m)\bigr)
 \quad\Longrightarrow\quad
 \bigl(\zeta_{t_1}(\phi_1),\ldots,
       \zeta_{t_m}(\phi_m)\bigr)
 \qquad(\eps\downarrow0).
\end{equation}
\end{theorem}

\begin{proposition}[Initial ensemble]\label{prop:initial}
For all sufficiently small $\eps$, the following assertions hold.
\begin{enumerate}[label=\textup{(\roman*)}]
\item The factorial densities satisfy
\begin{equation}\label{eq:initial-factorial-upper}
 0\le F_{h,0}^{\eps}\le\prod_{j=1}^h f_0(z_j),
 \qquad (1-C\eps)f_0\le g_0\le f_0.
\end{equation}
Consequently $\|g_0-f_0\|_{\Bol,2\beta}=O(\eps)$ and, for every
fixed integer $p\ge1$,
\begin{equation}\label{eq:initial-N-moments}
 \E(N)_p\le\mu^p,
 \qquad \sup_{0<\eps\le\eps_0}\E(N/\mu)^p<\infty.
\end{equation}
\item With $\upsilon=1/81$, for every $h\ge2$,
\begin{equation}\label{eq:initial-coarse-links}
 |c_{h,0}^{\eps}(Z_h)|
 \le (Ch)^{Ch}\prod_{j=1}^h f_0(z_j)
   \sum_{\mathcal T\text{ tree on }[h]}
     \prod_{\{i,j\}\in\mathcal T}
       \bigl(\ind_{|x_i-x_j|\le\eps}+\eps^\upsilon\bigr).
\end{equation}
Here $C$ and the upper bound on $\eps$ are independent of $h$.
For fixed $h\ge2$ and $D>0$ there is $C_{D,h}<\infty$ such that
\begin{equation}\label{eq:initial-sharp-links}
 |c_{h,0}^{\eps}(Z_h)|
 \le C_{D,h}\prod_{j=1}^h f_0(z_j)
   \sum_{\mathcal T\text{ tree on }[h]}
     \prod_{\{i,j\}\in\mathcal T}
       \bigl(\ind_{|x_i-x_j|\le C_{D,h}\eps}+\eps^D\bigr).
\end{equation}
Moreover,
\begin{equation}\label{eq:initial-integrated-cumulants}
 \|c_{h,0}^{\eps}\|_{L^1}\le C_h\eps^{3(h-1)}
 \qquad(h\ge2).
\end{equation}
\item For every finite list of bounded real tests, the exact-centered
initial fluctuations converge jointly to a centered Gaussian vector
with covariance $\int f_0\phi\psi$.
For a smooth compactly supported real test $\phi$, one also has
\begin{equation}\label{eq:initial-centering-shift}
 \lim_{\eps\to0}\sqrt\mu
 \left(\E\pi_0^\eps(\phi)-\int f_0\phi\right)
 =-\frac{4\pi}{3}\int_{\R^6}
       f_0(x,v)\phi(x,v)\varrho_0(x)\,\dd x\,\dd v.
\end{equation}
\end{enumerate}
\end{proposition}

\begin{lemma}[Global weighted integrability]\label{lem:target-moments}
For every $0<q<2\beta$,
\begin{equation}\label{eq:target-velocity-moments}
 \sup_{0\le t\le T}\int_{\R^6}
       f_t(x,v)e^{q|v|^2}\,\dd x\,\dd v<\infty.
\end{equation}
\end{lemma}

\begin{lemma}[Backward evolution]\label{lem:target-propagator}
For $0\le a<b<2\beta$ and $0\le r\le t\le T$, there is a bounded
backward propagator $U(r,t):E_a^0\to E_b^0$.  It solves
\begin{equation}\label{eq:target-backward-mild}
 U(r,t)h=\mathsf S_{t-r}h
   +\int_r^t\mathsf S_{s-r}K_sU(s,t)h\,\dd s,
\end{equation}
has the composition law with intermediate exponents, and is the
unique mild propagator in these scales.  For $\phi\in C_c^\infty$,
\begin{equation}\label{eq:target-upper-end-identity}
 U(r,t)\phi-\phi=\int_r^t U(r,s)A_s\phi\,\dd s.
\end{equation}
\end{lemma}

\begin{proposition}[Gaussian target]\label{prop:gaussian-target}
The fluctuation equation in \Cref{thm:main} has a centered Gaussian
solution on the test scales $E_a^0$, $0\le a<\beta$.  It is a
continuous linear map from each such test space to $L^2$ of its
probability space, uniformly on $[0,T]$.  Its covariance is
\begin{equation}\label{eq:target-covariance}
 \begin{split}
 \E[\zeta_t(\phi)\zeta_s(\psi)]
 ={}&\int f_0(z)\,U(0,t)\phi(z)\,U(0,s)\psi(z)\,\dd z\\
 &+\int_0^{\min(s,t)}
     C_r\bigl(U(r,t)\phi,U(r,s)\psi\bigr)\,\dd r.
 \end{split}
\end{equation}
It is unique in the class of solutions extending to these scales
with uniformly bounded second-moment operator norms.  In particular,
the law required in \Cref{thm:main} is well defined.
\end{proposition}

\begin{lemma}[Kinetic envelopes]\label{lem:kinetic-envelopes}
Under \Cref{ass:kinetic},
\begin{equation}\label{eq:kinetic-bol-propagated}
 \sup_{0\le t\le T}
 \bigl(\|f_t\|_{\Bol,\beta}
       +\|\nabla_x f_t\|_{\Bol,\beta}\bigr)<\infty.
\end{equation}
\end{lemma}

\begin{lemma}[Autonomous partition]\label{lem:autonomous-partition}
For a finite set $V$,
\begin{equation}\label{eq:autonomous-partition}
 \sum_{\mathcal C\in\mathcal P(V)}
 \prod_{C\in\mathcal C}\kappa_C
 \prod_{\{C,D\}\subseteq\mathcal C}\chi(C,D)=1.
\end{equation}
Here $\mathcal P(V)$ denotes the partitions of $V$.  If $S\subseteq V$ is a
root set and $H$ tests the root histories, then
\begin{equation}\label{eq:autonomous-observation}
 H(\Psi_V|_S)=
 \sum_{\mathcal C\in\mathcal P(V)}
 \prod_{C\in\mathcal C}\kappa_C
 \prod_{\{C,D\}\subseteq\mathcal C}\chi(C,D)
 H(\Psi_{\mathcal C}|_S),
\end{equation}
where $\Psi_{\mathcal C}$ is the juxtaposition of the autonomous histories.
\end{lemma}

\begin{lemma}[Rooted forest stopping]\label{lem:rooted-forest}
Let $W$ be a finite vertex set, let $R\subseteq W$ be nonempty, and attach
$a_e\in\{0,1\}$ to each unordered pair of vertices.  Fix $M\ge2$ and set
\begin{equation}\label{eq:ursell-block}
 u(B)=\sum_{\substack{G\text{ connected}\\V(G)=B}}
             \prod_{e\in E(G)}(-a_e),\qquad u(\{w\})=1.
\end{equation}
There is a finite signed remainder $\mathcal R$ such that
\begin{align}\label{eq:finite-rooted-identity}
 \prod_{e\subseteq W}(1-a_e)
 &=\sum_{I:\,R\subseteq I\subseteq W}
   \sum_{\substack{\mathcal B\in\mathcal P(I)\\
               B\cap R\ne\varnothing,\ |B|<M\ (B\in\mathcal B)}}
       \prod_{B\in\mathcal B}u(B)
       \prod_{e\subseteq W\setminus I}(1-a_e)+\mathcal R.
\end{align}
Its absolute value is bounded by a sum of rooted forests.  Each forest in
this bound has exactly one component with $M\le |B|\le2M-2$; its other
components have fewer than $M$ vertices.  All these components meet $R$.
Vertices outside the forest retain their full mutual compatibility
product.  The coefficient of each selected forest in this domination is
at most one.  Moreover,
\begin{equation}\label{eq:ursell-tree-bound}
 |u(B)|\le\sum_{T\text{ spanning tree on }B}\prod_{e\in E(T)}a_e.
\end{equation}
\end{lemma}

\begin{lemma}[One-slab identity and variation remainder]
\label{lem:one-slab-expansion}
For a positive input point-process law, let $F'$ be its factorial
hierarchy after the truncated slab.  If its factorial measures up to the
order in \eqref{eq:stopped-input-order} are finite, then
\begin{equation}\label{eq:one-slab-exact}
 F'_s=\mathcal L_sF+R_s,\qquad |R_s|\le\mathcal E_sF.
\end{equation}
The same statements hold with prescribed records on root labels.
The positive expression $\mathcal E_sF$ is a domination of $R_s$, not an
assertion that the signed remainder has this local kernel.
\end{lemma}

\begin{lemma}[Modified one-root bridge]\label{lem:one-root-bridge}
The difference between $\mathcal U_i(g)$ and the signed unrestricted
one-root particle-tree sum with $n<\Lambda_i/3$ is dominated, after
replacing inputs by $|g|$, by the following positive history integrals:
\begin{enumerate}[label=(\roman*)]
 \item retained one-root molecules with $r\ge1$;
 \item retained one-root molecules with $n\ge\Lambda_i/3$;
 \item the small unrestricted trees with one additional incoming O
 contact inserted between a pair of their flight segments.
\end{enumerate}
The first two families are subsets of the DHM one-root graph class.
The third is its additional-overlap error class.  Coefficients in these
dominations have at most a fixed power of the cutoffs.  The leading
tree coefficient is exactly $(-1)^{\#\mathrm O}$, with the labelled
factorial just stated.
\end{lemma}

\begin{proposition}[Independent factors]\label{prop:one-root}
The measures $g_i$ have Gaussian Bol-bounded density representatives.
With the exponents $\beta_i,\theta_i$ of
\Cref{thm:dhm-package}, for sufficiently small $\eps$,
\begin{equation}\label{eq:one-root-convergence}
 \|g_i-f_{i\tau}\|_{\Bol,\beta_i}\le\eps^{\theta_i},\qquad
 \sup_{0\le i\le L}\|g_i\|_{\Bol,\beta_i}\le C.
\end{equation}
The same estimates hold for the one-root map run through any portion
$\sigma\in[0,\tau]$ of slab $i$, with target
$f_{(i-1)\tau+\sigma}$ and exponent $\beta_i$.
\end{proposition}

\begin{lemma}[Resummation with specified records]
\label{lem:marked-regrouping}
The retained hierarchy admits an exact finite expansion
\begin{equation}\label{eq:dependent-subsets}
 \widehat F^R_{i,S}
   =\sum_{H:\,R\subseteq H\subseteq S}
        E^R_{i,H}\otimes g_i^{\otimes(S\setminus H)}.
\end{equation}
The coefficients can be represented by layered diagrams with the
following rule.  Every retained block in slab $i$ contains a root from
the interface above it.  A block is retained in $E^R_{i,H}$ if it
contains at least two such roots, or it meets a dependent input label
from the interface below.  All other blocks sum to the independent
factor $g_i$ on their unique root.  Every record-bearing line continues
to time zero.  Forgetting any record commutes with
\eqref{eq:retained-hierarchy}; at the diagram level it is effected by
resumming the newly unmarked one-root histories.
\end{lemma}

\begin{lemma}[Labels and connected components]\label{lem:diagram-labels}
The retained expansion factors over its global components.  If
$D^R_{i,B}$ is the sum of its diagrams connected on the designated roots
$B$, then
\begin{equation}\label{eq:component-exponential-formula}
 \widehat F^R_{i,S}
       =\sum_{\pi\in\mathcal P(S)}
                         \bigotimes_{B\in\pi}D^{R\cap B}_{i,B}.
\end{equation}
Consequently factorial-cumulant inversion of the retained hierarchy
keeps exactly its connected diagrams.  This assertion is unchanged by
the resummations into $g_i$.

At fixed root order $h=|S|$ and bounded DHM complexity $\rho\le K$,
let $n_i$ denote the number of
particle lines in slab $i$, and $j_i$ its fresh input labels.  The
labelled denominator is $\prod_i j_i!$, where
\begin{equation}\label{eq:bounded-crossing-factorials}
 n_i-j_i=O_{K,h,m,L}(1),\qquad
 \prod_i\frac1{j_i!}
      \le\frac{(1+\sum_i n_i)^{C_{K,h,m,L}}}{\prod_i n_i!}.
\end{equation}
Apart from the choices of ordinary contact pairs and their order, all
distinguished-label, gluing, initial-block, and record-placement
multiplicities are bounded by a fixed polynomial in total size times
$C^b$, where $b$ is the atom count and the exponential base $C$ does not
depend on $K$ or the moment order.  In the coarse regime the same
choices cost a power of the cutoffs with exponent $O(\rho)$, in addition
to the exponential atom factor.
\end{lemma}

\begin{lemma}[Stopped variation errors]\label{lem:stopped-variation}
Choose $L$ sufficiently large in terms of the fixed data and $\Gamma$.
For any fixed bound on the number of recorded labels, there are
$c_i>0$ such that
\begin{equation}\label{eq:retained-variation-error}
 \|F^R_{i,S}-\widehat F^R_{i,S}\|_{\TV}
                  \le e^{-c_i\Lambda_i},
 \qquad |S|\le A_i/2.
\end{equation}
The constants may decrease with $i$ and the fixed record bound.
The statement is uniform for a partial final slab.  No velocity weight
is claimed for this error.
\end{lemma}

\begin{proposition}[Accuracy of the pasted dynamics]\label{prop:cutoff}
There is a sufficiently large dimensional integer \(\Gamma_0\) with the
following property.  Fix \(\Gamma\geq\Gamma_0\).  There is
\(L_0=L_0(\Gamma,f_0,f,T,\beta)\) such that, for any fixed \(L\geq L_0\),
the true dynamics and the pasted dynamics of
\Cref{thm:marked-expansion}, coupled using the same initial configuration,
satisfy
\begin{equation}\label{eq:cutoff-probability}
 \P\{\text{the two trajectories differ at some time in }[0,T]\}
 \leq C\eps^{1+\eta}
\end{equation}
for all sufficiently small \(\eps\), where one may take
\(\eta=1/20\).  Here the size cutoffs are the \(A_i,\Lambda_i\) of
\Cref{thm:dhm-package}, and \(C\) and the upper bound on \(\eps\) may
depend on the displayed fixed parameters.
\end{proposition}

\begin{lemma}[Removal of very high birth energy]\label{lem:cutoff-energy-tail}
For the positive graph majorants in
\eqref{eq:cutoff-low-complexity}, there is a fixed power \(H_*\)
such that restricting the total birth energy
\(P=\sum_{j\text{ a birth}}|v_j|^2\) to
\[
 P\leq P_{\eps}:=(1+|\log\eps|)^{H_*}
\]
changes their sum by \(O(\eps^M)\) for every fixed \(M\).
\end{lemma}

\begin{lemma}[Local adjacent-pair estimates]\label{lem:cutoff-pair}
Consider every possible choice $e_1,e_2$ of the two prospective fixed
edges of a type-A pair, with $t_1,t_2$ the corresponding contact times.
Call that choice strongly close if
\begin{equation}\label{eq:cutoff-close}
 |t_2-t_1|\leq\eps^{9/10},\qquad
 |v_{e_2}-v_{e_1}|\leq\eps^{4/5}.
\end{equation}
Then:
\begin{enumerate}[label=\textup{(\roman*)}]
\item a primitive pair satisfying \eqref{eq:cutoff-close}, cut
freely as one piece, has mass at most
\begin{equation}\label{eq:cutoff-free-pair}
 C R^C\mu\eps^{9/10+3(4/5)}
 =C R^C\eps^{13/10};
\end{equation}
\item in the absence of every strongly close primitive pair, each
type-A pair used by a cutting sequence has conditional mass at most
\(C R^C\eps^{1/20}\), or may be split into a neutral type-two
piece and a singleton with this same improved bound.
\end{enumerate}
The conditional bounds are uniform in the previously exposed lines
and times.
\end{lemma}

\begin{lemma}[Summation with finitely many exceptional pieces]\label{lem:cutoff-sum}
Consider the positive low-complexity graph integrals obtained
above.  Suppose a cut sequence has \(q=b-O_K(1)\) ordinary
atoms and boundedly many exceptional pieces, whose conditional
mass bounds have product
\(\eps^\alpha|\log\eps|^{C_*}\).
After summing spatial cells and energy bins in a polylogarithmic
energy region, its integral is at most
\begin{equation}\label{eq:cutoff-sum}
 \eps^\alpha|\log\eps|^{C_*}
       (C\tau\sqrt L)^q .
\end{equation}
The exponential base \(C\) depends on the fixed kinetic
envelopes and dimension, but not on \(K,L\).
\end{lemma}

\begin{lemma}[The fresh-label factorials]\label{lem:sharp-factorials}
For diagrams of complexity at most \(K\), the absolute sum with slab
sizes \((n_1,\ldots,n_L)\) is bounded by a sum over chronologically
ordered merger pair lists with denominator \(\prod_i n_i!\), multiplied
by
\begin{equation}\label{eq:sharp-polynomial-count}
 C_K(1+n)^{d_K}C^{\sum_i a_i},
 \qquad n=\sum_i n_i,
\end{equation}
where the base \(C\) does not depend on \(K\).  The merger pairs
themselves are not counted in \eqref{eq:sharp-polynomial-count}.
\end{lemma}

\begin{lemma}[Uniform summability]\label{lem:sharp-summability}
For fixed \(K\), the sum of the absolute connected diagram measures
with slab sizes \((n_i)\), after removal of the factor
\(\mu^{1-h}\), is bounded by
\begin{equation}\label{eq:sharp-summable}
       C_K(1+n)^{d_K}(C\tau\sqrt L)^n.
\end{equation}
The same bound, with the appropriate factor \(\mu^{c-h}\), holds
after a bounded number of initial links are erased.  It also holds
after prescribing the absolute spatial position of one observation
in each component, or after inserting a sufficiently small Gaussian
weight in the designated velocities.
\end{lemma}

\begin{proposition}[Evolution of the marked tree laws]
\label{prop:tree-evolution}
Between observation updates the limiting measures satisfy
\begin{align}
 \partial_tF_t(\Phi)
  &=F_t(D\Phi)+\frac12\int BF_tF_{t,*}\Delta\Phi,
       \label{eq:limit-F-evolution}\\
 \partial_tJ_t(\Phi\otimes\Psi)
  &=J_t\bigl((D+H_t)\Phi\otimes\Psi
                     +\Phi\otimes(D+H_t)\Psi\bigr)\notag\\
  &\quad+\int BF_tF_{t,*}
          \bigl(\Phi(\xi')\Psi(\xi_*')
                         -\Phi(\xi)\Psi(\xi_*)\bigr).
       \label{eq:limit-J-evolution}
\end{align}
The identities hold in transport mild form, and hence in weak
differential form for smooth tests for which the displayed integrals
exist.  At an update \(t_j\),
\begin{equation}\label{eq:limit-pushforwards}
       F_{t_j+}=(\Theta_j)_\#F_{t_j-},
       \qquad
       J_{t_j+}=(\Theta_j\otimes\Theta_j)_\#J_{t_j-}.
\end{equation}
\end{proposition}

\begin{maintheorem}[Regular-lifespan kinetic limit]\label{thm:main}
Let $\Phi$ satisfy Assumption~\ref{pre:potential}, and let $\beta>0$.
Let $f_0\ge0$ be a $C^1$ probability density on $\R^3\times\R^3$ such that
\begin{equation}\label{intro:data-bound}
 \|f_0\|_{\mathrm{Bol},2\beta}
 +\|\nabla_xf_0\|_{\mathrm{Bol},2\beta}<\infty.
\end{equation}
Fix $0<T<\infty$ for which the equation
\begin{equation}\label{intro:boltzmann}
 (\partial_t+v\cdot\nabla_x)f=Q_\Phi(f,f),
 \qquad f|_{t=0}=f_0,
\end{equation}
has a nonnegative classical probability-density solution satisfying
\begin{equation}\label{intro:solution-bound}
 \sup_{0\le t\le T}\sup_{x,v}
 e^{2\beta|v|^2}f(t,x,v)<\infty.
\end{equation}
Start the exact Newtonian process from the grand-canonical law
\eqref{pre:model}. For its scaled factorial densities
$F_s^\varepsilon$, defined in \eqref{pre:factorial}, every fixed
integer $s\ge1$ satisfies
\begin{equation}\label{intro:chaos}
 \lim_{\varepsilon\downarrow0}\;
 \sup_{0\le t\le T}
 \bigl\|F_s^\varepsilon(t)-f(t)^{\otimes s}\bigr\|_
 {L^1((\R^3\times\R^3)^s)}=0.
\end{equation}
\end{maintheorem}

\begin{maincorollary}[Empirical observables]\label{cor:empirical}
Under the hypotheses of Theorem~\ref{thm:main}, let
$a\in C_c^\infty(\R^3\times\R^3;\R)$ and $\eta>0$. Then
\begin{equation}\label{intro:empirical}
 \lim_{\varepsilon\downarrow0}\;
 \sup_{0\le t\le T}
 \PP\!\left(
 \left|\mu_\varepsilon^{-1}\sum_{i=1}^{N}a(z_i(t))
       -\int a(z)f(t,z)\,dz\right|>\eta\right)=0.
\end{equation}
\end{maincorollary}

\begin{assumption}[Potential class]\label{pre:potential}
Write $\Phi(q)=\phi(|q|)$, with $\Phi(q)=0$ for $|q|\geq1$.
Assume either $\Phi\in C^2(\mathbb R^3;\mathbb R)$, or
$\Phi\in C^2(\mathbb R^3\setminus\{0\})$ with
$\Phi(q)\to+\infty$ as $q\to0$.
In the latter case set $\Phi(0)=+\infty$.
Assume thermodynamic stability: for some $B\geq0$,
\begin{equation}\label{eq:pre-stability}
 \sum_{\substack{i,j\in R\\i<j}}\Phi(q_i-q_j)\geq-B|R|
\end{equation}
for every finite configuration of distinct points.
The potential is fixed independently of $\varepsilon$.
\end{assumption}

\begin{proposition}[Initial insertion and centering]\label{pre:initial}
Put $\rho_0(x)=\int f_0(x,v)\,dv$, and assume $\|\rho_0\|_\infty<\infty$.
At time zero,
\begin{equation}\label{eq:pre-insertion}
 \begin{split}
 \widetilde F_R^\varepsilon(0,Z_R)
 &=F_R^\varepsilon(0,Z_R)\\
 &=f_0^{\otimes R}(Z_R)\mathbf1_{{\cal D}_R^\varepsilon}(Z_R)
       \mathbb E\prod_{i\in R}\mathbf1_{\{N(B_i)=0\}},
 \qquad B_i=\overline B(x_i,\varepsilon).
 \end{split}
\end{equation}
The expectation is over an independent cloud with the original law,
and $N(B)$ counts its positions in $B$.
Consequently $0\leq F_R^\varepsilon(0)\leq f_0^{\otimes R}$.

For $Z_R\in{\cal D}_R^\varepsilon$, define
\begin{equation}\label{eq:pre-initialcenter}
 E_R^\varepsilon(0,Z_R)=
 \sum_{S\subset R}(-1)^{|R\setminus S|}
      f_0^{\otimes(R\setminus S)}(Z_{R\setminus S})
      \widetilde F_S^\varepsilon(0,Z_S).
\end{equation}
There are $c_0>0,C_0<\infty$, independent of $R,\varepsilon$, such that
for sufficiently small $\varepsilon$,
\begin{equation}\label{eq:pre-centersmall}
 |E_R^\varepsilon(0,Z_R)|
       \leq(C_0\varepsilon^{c_0})^{|R|}f_0^{\otimes R}(Z_R).
\end{equation}
One may take $c_0=1/125$.
For fixed $r$,
\begin{equation}\label{eq:pre-mass}
 0\leq1-\int F_R^\varepsilon(0,Z_R)\,dZ_R
       \leq Cr\varepsilon+Cr^2\varepsilon^3,
 \qquad \int F_R^\varepsilon(t)=\int F_R^\varepsilon(0).
\end{equation}
\end{proposition}

\begin{lemma}[Residence-time flux]\label{pre:duration}
For every $M<\infty$ there is $C_M<\infty$ such that
\begin{equation}\label{eq:pre-duration}
 \int_{\substack{|g|\leq M\\n\in S^2,\ n\cdot g<0}}
 \tau_*(n,g)|n\cdot g|\,d\sigma(n)\,dg\leq C_M.
\end{equation}
The incoming flux of $\{\tau_*>D,\ |g|\leq M\}$ is at most $C_M/D$.
In particular $\tau_*<\infty$ almost everywhere in incoming flux.
The entrance-to-exit scattering map preserves flux.
\end{lemma}

\begin{definition}[The scattering collision operator]
Write $c=(v+v_*)/2$, $g=v-v_*$, and, for almost every incoming datum,
let $g_{\rm out}$ be the velocity after exit. Set
\[
 v'=c+\tfrac12g_{\rm out},\qquad
 v_*'=c-\tfrac12g_{\rm out}.
\]
For $\psi\in C_c^\infty(\mathbb R^3)$, define $Q_\Phi$ at each $x$ by
\begin{equation}\label{pre:collision}
 \begin{split}
 \int Q_\Phi(f,f)(x,v)\psi(v)\,dv
 =\frac12\int_{\mathbb R^3\times\mathbb R^3}
 & f(x,v)f(x,v_*)|v-v_*|\\
 {}\times\int_{\substack{b\in(v-v_*)^\perp\\|b|<1}}
 &[\,\psi(v')+\psi(v_*')-\psi(v)-\psi(v_*)\,]\,
                         d^2b\,dv\,dv_* .
 \end{split}
\end{equation}
Here $d^2b$ is Euclidean area, and the $g=0$ contribution is zero.
Null exceptional scattering data are ignored.
\end{definition}

\begin{lemma}[Reversibility and normalization]\label{pre:operator}
The measure $d\Lambda=|v-v_*|\,dv\,dv_*\,d^2b$ is preserved by
exchanging incoming and outgoing velocity pairs with the corresponding
entrance parameter. The weak definition \eqref{pre:collision} equals
\begin{equation}\label{eq:pre-Qstrong}
 Q_\Phi(f,f)(x,v)=
 \int_{\mathbb R^3}|v-v_*|
 \int_{\substack{b\in(v-v_*)^\perp\\|b|<1}}
 [\,f(x,v')f(x,v_*')-f(x,v)f(x,v_*)\,]\,d^2b\,dv_* .
\end{equation}
These identities hold whenever the integrals are absolutely convergent,
in particular for Gaussian bounded functions. All scattering branches
are included, and the impact disk has area $\pi$.
\end{lemma}

\begin{proposition}[Known-solution envelopes]\label{pre:envelopes}
Suppose $f$ is the classical nonnegative solution in the statement, and
\[
 A=\sup_{0\leq t\leq T}\|f(t)\|_{\infty,2\beta}<\infty,\qquad
 B_0=\|f_0\|_{\mathrm{Bol},2\beta}
               +\|\nabla_xf_0\|_{\mathrm{Bol},2\beta}<\infty.
\]
Then
\begin{equation}\label{eq:pre-envelope}
 \sup_{0\leq t\leq T}
 \left(\|f(t)\|_{\mathrm{Bol},\beta}
       +\|\nabla_xf(t)\|_{\mathrm{Bol},\beta}\right)
       \leq C(A,B_0,\beta,T)<\infty.
\end{equation}
Fix, once and for all,
\begin{equation}\label{eq:pre-beta0}
 \beta_0=\beta/2.
\end{equation}
Thus all independent inputs $f(t)$ and their spatial Lipschitz
envelopes have a common bound with the fixed margin
$\beta-\beta_0$. Constants in \eqref{eq:pre-envelope} are independent
of the subsequent time-layer subdivision.
\end{proposition}

\begin{proposition}[Exact cell expansion]
\label{cell:expansion}
Let $R\subset S$ and let $A_0$ be the union of the blocks of
$\pi_0(S)$ meeting $R$.  For $R\ne\varnothing$, let $\mathcal P$ be
the collection of the other blocks of $\pi_0(S)$.  Then
\begin{equation}
 \mathsf H^I_{R,S}
 =\sum_{\mathcal U\subset\mathcal P}
      \mathsf K^I_{R,A_0\cup\bigcup\mathcal U},
 \label{eq:cell-subset-sum}
\end{equation}
and, as an equality of signed measures,
\begin{equation}
 \mathsf K^I_{R,A_0\cup\bigcup\mathcal U}
  =\sum_{\mathcal V\subset\mathcal U}
       (-1)^{|\mathcal U|-|\mathcal V|}
       \mathsf H^I_{R,A_0\cup\bigcup\mathcal V}.
 \label{eq:cell-boolean}
\end{equation}
Every coefficient is evaluated on its displayed input coordinates.
If $m=|S\setminus R|$, the number of diagrams in
\eqref{eq:cell-K} is at most $(C(1+m))^{Cm}$, with a universal $C$.
There is no partition of the roots in this count.
\end{proposition}

\begin{corollary}[Factorial normalization]
\label{cor:cell-factorial}
For the actual microscopic cloud and $r=|R|$, the cell identity is
written after relabelling the ordered roots as $R=\{1,\ldots,r\}$:
\begin{equation}
 \widetilde F_R(b)
  =\sum_{m\geq0}\frac{\mu^m}{m!}
       \mathcal T^I_{R,R\sqcup\{r+1,\ldots,r+m\}}
       \widetilde F_{r+m}(a).
 \label{eq:cell-factorial}
\end{equation}
The right side is interpreted with each finite Boolean coefficient
grouped before summing over $m$.  Equivalently, one may first restrict
the ensemble to $N\leq M$, apply the finite identity, and then let
$M\to\infty$.  No assertion of absolute summability of the
\emph{ungrouped} generation series is made here.
\end{corollary}

\begin{proposition}[Diagramwise factorization]
\label{cell:factorization}
Split the labels into $S=S_1\sqcup S_2$ and the roots into
$R=R_1\sqcup R_2$, where $R_i\subset S_i$.  Let $\gamma_i$ be a
diagram on $(R_i,S_i)$.  Define $\eta_I(\gamma_1,\gamma_2)$ to be the
indicator that every displayed particle trajectory of $\gamma_1$
has distance greater than $\varepsilon$ throughout $I$ from every
displayed trajectory of $\gamma_2$.  This includes detached groups
and includes the initial and terminal times.
For a single global diagram $\gamma$, define
$\eta_I(\gamma;S_1,S_2)$ by the same condition between its labelled
paths in $S_1$ and $S_2$, using their prescribed force-group flows.

On this indicator, merge the two root groups, and take the union of
the two batches at each generation, padding a finished list by empty
batches.  This gives a diagram on $(R,S)$.  Conversely, every nonzero
diagram term satisfying $\eta_I(\gamma;S_1,S_2)=1$ splits uniquely in
this manner.  Its detached groups necessarily belong to one $S_i$,
and its root flow splits over its two intersections with $S_i$.
Under this bijection the signed transport measures, with this
indicator imposed, agree with the tensor product of the two
diagram transport measures:
\begin{equation}
 \sigma(\gamma)w_I(\gamma)\mathsf H^I_{R,A}\,\eta_I
  =\eta_I\bigl[
       \sigma(\gamma_1)w_I(\gamma_1)\mathsf H^I_{R_1,A_1}
       \otimes
       \sigma(\gamma_2)w_I(\gamma_2)\mathsf H^I_{R_2,A_2}
             \bigr].
 \label{eq:cell-factorization}
\end{equation}
Summation over the bijection preserves this equality.  Factorial
weights split as
\begin{equation}
 \binom{m_1+m_2}{m_1}
       \frac{\mu^{m_1+m_2}}{(m_1+m_2)!}
   =\frac{\mu^{m_1}}{m_1!}\frac{\mu^{m_2}}{m_2!}.
 \label{eq:cell-factorial-split}
\end{equation}
\end{proposition}

\begin{definition}[Patternwise centered marginal]\label{cent:definition}
The centered marginal on pattern $\pi$ is
\begin{equation}\label{cent:definition-eq}
 E_\pi^\eps(t,Z_R)=\chi_\pi^\eps(Z_R)
 \sum_{A\subset S(\pi)}(-1)^{|S(\pi)\setminus A|}
 f_{S(\pi)\setminus A}(t,Z_{S(\pi)\setminus A})
 \widetilde F_{B(\pi)\cup A}^\eps(t,Z_{B(\pi)\cup A}).
\end{equation}
We set $E_\varnothing^\eps=1$. A nonsingleton block is always retained
as a whole; its individual labels are not centered.
\end{definition}

\begin{proposition}[Centering and inversion]\label{cent:identity}
For every $\pi$ and almost every $Z_R$,
\begin{equation}\label{cent:inverse}
 \chi_\pi^\eps\widetilde F_R^\eps(t)
 =\chi_\pi^\eps
 \sum_{A\subset S(\pi)}f_{S(\pi)\setminus A}(t)
 E_{\pi_A}^\eps(t).
\end{equation}
Both formulas hold for arbitrary factorial densities, without a
smallness or factorization assumption.
\end{proposition}

\begin{proposition}[Short-layer residual]\label{cent:residual}
Set $\beta_0=\beta/2$. There is $b_*>0$, depending only on the fixed
bounds in Proposition~\ref{pre:envelopes}, for which the following
holds. Suppose $b\leq b_*$, $K(\eps)\to\infty$, and
$J(\eps)\to\infty$ is a fixed power of $1+|\log\eps|$.
Then
\begin{equation}\label{cent:residual-def}
 r_{u,t}^{\eps}=f(t)-\mathscr G_{u,t}^{\eps,J,K},\qquad
 \sup_{\substack{0\leq u\leq t\leq T\\t-u\leq b}}
 \|r_{u,t}^{\eps}\|_{\mathrm{Bol},\beta_0}
 =:\eta_\eps\longrightarrow0.
\end{equation}
All the reference sums and residuals have uniformly bounded norms at
this one fixed exponent. The proof uses only short-layer tree
summability and two-body scattering.
\end{proposition}

\begin{lemma}[Augmented volume and the once-counted Gaussian]
\label{hist:gaussian}
For every fixed prescription $\Gamma$, the map from its $p$ source
coordinates to $\widehat Z(t)$ is one-to-one and volume preserving
outside null sets.  On $\mathcal D_\Gamma$,
\begin{equation}
 \sum_{i=1}^p|\widehat v_i(t)|^2\leq S+2Bp,
 \qquad
 \sup_{0\leq t\leq T}\sum_{\substack{i:\,i\text{ active at }t}}|v_i(t)|^2
       \leq S+2Bp.
 \label{eq:hist-mixed-energy}
\end{equation}
In particular, with $V(t)=(\widehat v_i(t))_{i=1}^p$,
\begin{equation}
 e^{-\beta_0 S}
 \leq e^{\beta_0Bp}
       e^{-\beta_0|V(t)|^2/2}e^{-\beta_0 S/2}.
 \label{eq:hist-split-gaussian}
\end{equation}
The same assertions hold at the last time, when the mixed coordinates
consist of the top coordinates and the departure coordinates of every
other label.  The exponent in \eqref{eq:hist-split-gaussian} is not
changed at a layer cut.
\end{lemma}

\begin{proposition}[Finite-term bound with its time factors]
\label{hist:basic}
Fix $A<\infty$ and the finite number $L$ of layers.  There is a
numerical exponent $d$ in the cell estimates such that, if
$J=\lceil P^Q\rceil$ with $Q>2dA$, all the following bounds hold
uniformly for $1\leq p\leq P^A$, for sufficiently small $\varepsilon$.
Put $n_j$ for the total additions in layer $j$, $h_j$ for its incoming
roots, and $q_j=h_j+n_j$.  After summing cell choices, cell diagrams,
and original parents, the absolute integral on the shell
\eqref{eq:hist-shells} is bounded by
\begin{align}
 &\eta_\Gamma C^p e^{-c rp}\mathsf S(h_0,E_r)
       \chi_\varepsilon^{m_*+o_*}(r+2)^{(m_*+o_*)/2}
       \prod_{j=1}^L\frac{b^{n_j}q_j^{n_j}}{n_j!}
 \nonumber\\[-2pt]
 &\hspace{22mm}\times
  \int_{\mathbb R^{3p}}
       \prod_{\substack{i:\,i\text{ an ordinary pin}}}
          \left(1+|w_i|^2+\frac{E_r}{q_{j(i)}}\right)^{1/2}
       d\gamma(V),
 \label{eq:hist-finite-bound}
\end{align}
where $d\gamma$ is a normalized product Gaussian of one fixed exponent,
the integral may retain the common indicator $|V|^2\leq E_r$,
and one may take
\begin{equation}
 \chi_\varepsilon
   = C P^{dA}\left(J^{-1/2}+\frac{\varepsilon J}{b}\right).
 \label{eq:hist-mesh-gain}
\end{equation}
Harmless increases of $d$ absorb the fixed extra powers occurring in
the finite diagrams.  Constants $C,c$ in
\eqref{eq:hist-finite-bound} do not depend on $L$ or on later rarity
cutoffs.  The threshold of sufficiently small $\varepsilon$ may
depend on the fixed $b=T/L$.

In particular, after summing layer occupancies and retained slots the
total finite integral of order $p$ is at most
\begin{equation}
 \eta_\Gamma C_L^p.
 \label{eq:hist-coarse-exponential}
\end{equation}
Its portion with $S>Rp$ is at most
\begin{equation}
 \eta_\Gamma C_L^p e^{-cRp},
 \label{eq:hist-source-tail}
\end{equation}
after changing $c>0$ and taking $R$ above a fixed constant.
These are estimates of finite independently enveloped terms, not
assertions about the actual process.
\end{proposition}

\begin{lemma}[A fixed-pivot forest]
\label{hist:pivot}
Fix a time $t_*$, a forest of $r$ edges on the $p$ labels, and
$\rho\geq\varepsilon$.  For one fixed force/lifetime prescription
whose required contacts connect every label to a top, the source integral
before multiplication by $\mu^{p-h_0}$, on $S\leq Rp$ with
$|x_i(t_*)-x_j(t_*)|\leq\rho$ on every forest edge is at most
\begin{equation}
 \eta_\Gamma C^p p^{Cp}\rho^{3r}
       \varepsilon^{2(p-r-h_0)_+}.
 \label{eq:hist-pivot-bound}
\end{equation}
More precisely, a stratum with $k$ final translation components has
the factor $\rho^{3r}\varepsilon^{2(p-r-k)}$, with $k\leq h_0$.
There is no factor equal to the number of cells in this geometric
bound.
\end{lemma}

\begin{proposition}[Extensive simultaneous crowding]
\label{hist:crowding}
Fix $A,Q,L,R$ and $\delta>0$.  Among independently enveloped finite
histories with $p\leq P^A$ and $S\leq Rp$, the activity-normalized integral
for which at some time at least $\delta p$ displayed labels have a
companion within $\rho=\varepsilon^{.85}$ is bounded by
\begin{equation}
 \eta_\Gamma P^{C_{A,Q,L,R}p}
       \varepsilon^{.275\delta p-1}.
 \label{eq:hist-crowding-explicit}
\end{equation}
For $\delta p\geq8$ this is at most
$\eta_\Gamma\varepsilon^{.1\delta p}$ for sufficiently small
$\varepsilon$, uniformly in the stated range of $p$.
\end{proposition}

\begin{lemma}[Premature contacts in original coordinates]
\label{exp:rerouting}
Outside the original compact-parameter, crowded-parent, and multi-addition
exceptions, the contribution with a specified set of $k$ singleton cells
having a premature contact has bound
\begin{equation}
\label{exp:reroute-bound}
 C_L^p\bigl(p^C\varepsilon^c\bigr)^k.
\end{equation}
Consequently an extensive number of premature contacts has arbitrarily
strong exponential suppression.  The remaining premature births may be
marked irregular before selecting terminal subtrees.  No global
reparenting multiplicity is included or needed in this estimate.
\end{lemma}

\begin{proposition}[Causal exposure for mixed prescriptions]
\label{exp:exposure}
Fix an admissible mixed whole-cell prescription with $p\le P^a$ labels and
a total energy budget $\mathcal K\le Rp$.  Fix a collection of $k$ disjoint
regular terminal trees as in Lemma~\ref{exp:terminal}.  Sum the absolute
activity-normalized chart integrals over the event that every selected tree has a
first defect.  The result is bounded by
\begin{equation}
\label{exp:exposure-bound}
 \mathcal A_p\,(pJ)^{C p}\bigl(p^C\varepsilon^c\bigr)^{k/2},
\end{equation}
The factor $(pJ)^{Cp}$ includes cell-segment choices.  Constants may
depend on the fixed layer count, compact cutoffs, $M$, and $R$.
\end{proposition}

\begin{lemma}[Retained-slot entropy]\label{close:entropy}
Suppose a term retains $k_j$ slots among $q_j$ available slots at
successive cuts. Put $Q=\sum_jq_j$ and $H'=\sum_jk_j$. Then
\begin{equation}\label{close:slot-bound}
 \prod_j\binom{q_j}{k_j}
 \leq\binom{Q}{H'}
 \leq\exp\left\{H'\log\frac{eQ}{H'}\right\}
 \quad (H'>0).
\end{equation}
In the history expansion $Q\leq p+C H$ and $H'\leq C H$, up to a
fixed number of choices per retained slot. Consequently, when $H\leq\delta p$,
the logarithmic selection cost is at most
\begin{equation}\label{close:entropy-small}
 C\delta p\left(1+\log\frac1\delta\right).
\end{equation}
For general $H\leq Lp$, its cost is at most $C_L^p$.
\end{lemma}

\begin{lemma}[Energy and the short-layer factors]\label{close:energy}
For a completed history with the above counts, the parent, time,
and velocity factors in Proposition~\ref{hist:basic}, before
retained-slot and spatial losses, have total integral at most
\begin{equation}\label{close:energy-factor}
 (C b\sqrt L)^p
 \exp\{H+h_0\log_+(1/b)\},
 \qquad b\leq1.
\end{equation}
The constant $C$ is independent of $L$. A fixed part of the source
Gaussian remains available for the spatial estimates.
\end{lemma}

\begin{lemma}[Integrated amplification and bad clouds]
\label{close:amplification}
Consider a finite completed block containing at most $M$ labels
and acting on an input signed array in integrated total variation.
For $M$ and $J$ bounded by fixed powers of $P$, its operator norm
is at most
\begin{equation}\label{close:raw-amplification}
 \exp(C_LMP).
\end{equation}
The same bound holds for the pattern-summed centered norm of
\eqref{cent:centering-norm}. If a physical layer is stopped below
$K$ labels, the contribution of a
microscopic event $\mathcal A$ to the exact observable minus its
completed physical below-$K$ expansion is at most
\begin{equation}\label{close:bad-discard}
 \exp(C_LKP)\,\mathbb P(\mathcal A)^{1/2},
\end{equation}
provided its upper root count is less than $K$. This discard is
made before estimating any overshoot.
\end{lemma}

\begin{proposition}[Actual witnesses and layer remainders]
\label{close:tails}
With the preceding schedule, for sufficiently small
$\varepsilon$ and every $1\leq j\leq L$,
\begin{equation}\label{close:actual-tail-bounds}
 \mathbb P\bigl(\mathcal B_j(D_j)\bigr)\leq e^{-8D_j},
 \qquad R_j\leq e^{-8K_j}.
\end{equation}
The estimates use the original Newtonian process, without
conditioning it to stay in a good set.
\end{proposition}
